// === Tab: mySketch ===
// Basic structure ref: https://itp-xstory.github.io/p5js-shaders/#/./docs/setting-up-shaders-in-p5

let theShader;
let WebGL;
let Canvas;
let img;

function preload(){
  theShader = createShader(vert, frag);
}

function setup() {
  createCanvas(1112, 834);
  pixelDensity(1);
  WebGL = createGraphics(width, height, WEBGL);
  Canvas = createGraphics(width, height);
  noStroke();
}

function draw() {
  WebGL.shader(theShader);

  theShader.setUniform('iResolution', [width, height]);
	theShader.setUniform('iPixelDensity', pixelDensity());
	theShader.setUniform('iCanvas', Canvas);
  theShader.setUniform('iMouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  theShader.setUniform('iTime', frameCount);

  WebGL.rect(0, 0, width, height);

  image(WebGL, 0, 0);

  //noLoop();
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg"); 
    lapse = millis();
  } 
}


