	#define PI 3.141592653589793
	#define TWO_PI 6.283185307179586

	vec2 conical(vec2 uv, vec2 pos, float tile, float ofst) {
		uv -= pos;
		//uv.x *= iResolution.x/iResolution.y;  // square
		vec2 radialUv = vec2(atan(uv.y, uv.x)/TWO_PI+0.5, length(uv));
		//radialUv.x += radialUv.y*1.; // Swirl
		radialUv = radialUv*tile-fract(ofst);
		return fract(radialUv);
	}

	float horizontal(vec2 uv, float tile, float ofst) {
		return fract( (uv*tile)-ofst ).x;
	}

	float radial(vec2 uv, vec2 pos, float tile, float ofst) {
		uv -= pos;
		//uv.x *= iResolution.x/iResolution.y;  // square
		float d = length(uv);
		d = d*tile-fract(ofst);
		return fract(d);
	}

	float vertical(vec2 uv, float tile, float ofst) {
		return fract( (uv*tile)-ofst ).y;
	}
`

// === Tab: Palette ===
// noprotect

const Palette = `
	// MIT License
	// Copyright © 2023 Zaron
	// Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:
	// The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.
	// THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.

	float pulse(float start, float end) {
		return step(0., start) * step(end, 0.);
	}

	vec4 grad(float area, vec4 startCol, vec4 endCol, float startPos, float endPos) {
		float u = pulse(area-startPos, area-endPos);
		vec4 gradientCol = mix(startCol, endCol, (area-startPos)/(endPos-startPos))*u;
		return gradientCol;
	}

	vec4 Palette(vec2 puv) {
		// define your colors
		vec4 cols[7];
		cols[0] = vec4(1., 0., 0., 1.);    // red
		cols[1] = vec4(1., 1., 0., 1.);    // yellow
		cols[2] = vec4(0., 1., 0., 1.);     // green
		cols[3] = vec4(0., 1., 1., 1.);    // cyan
		cols[4] = vec4(0., 0., 1., 1.);    // blue
		cols[5] = vec4(1., 0., 1., 1.);    // magenta
		cols[6] = vec4(1., 0., 0., 1.);    // red 

		// define positions of your colors (0.0 - 1.0)
		float pos[7];
		pos[0] = 0.00;    // red
		pos[1] = 0.13;    // yellow
		pos[2] = 0.35;    // green
		pos[3] = 0.48;    // cyan
		pos[4] = 0.66;    // blue
    pos[5] = 0.76;    // magenta
		pos[6] = 1.00;    // red

		vec4 result_color = vec4(0.);
		for (int i = 0; i < 6; i++) {
			result_color += grad(puv.x, cols[i], cols[i+1], pos[i], pos[i+1]);
		}

		return result_color;
	}
`

// === Tab: frag ===
// noprotect

const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	uniform vec2 iResolution;
	uniform float iPixelDensity;
	uniform sampler2D iCanvas;
	uniform vec2 iMouse;
	uniform float iTime;

	${ gradient }
	${ Palette }

	varying vec2 vTexCoord;
	void main() {
		vec2 uv = vTexCoord;
		vec2 iuv = floor(uv*2.);
		vec2 fuv = fract(uv*2.);

		// gradient uv
		vec2 guv;
		float tile = 3.;
		float ofst = sin(iTime*0.01);

		// top left, horizontal gradient
		if (iuv == vec2(0., 1.)) {
			guv = vec2(horizontal(fuv, tile, ofst));
		}

		// bottom left, radial gradient
		if (iuv == vec2(0., 0.)) {
			guv = vec2(radial(fuv, vec2(.5), tile, ofst));
		}

		// top right, vertical gradient
		if (iuv == vec2(1., 1.)) {
			guv = vec2(vertical(fuv, tile, ofst));
		}

		// bottom right, conical gradient
		if (iuv == vec2(1., 0.)) {
			guv = vec2(conical(fuv, vec2(.5), tile, ofst));
		}

		gl_FragColor = Palette(guv);
	}
`

// === Tab: vert ===
// Basic structure ref: https://itp-xstory.github.io/p5js-shaders/#/./docs/how-to-write-a-shader

const vert = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
		gl_Position = positionVec4;
	}
`

